R=api.ROOT;O=R/'results/ru45-captions';O.mkdir(parents=True,exist_ok=True);sources=json.loads((R/'inputs/ru45-caption-input.json').read_text());api.save(O/'input.json',sources);current=api.validate([{'source_id':s['id'],'target':s['draft_target']} for s in sources],sources);turns=[]
for phase in range(8):
 task='Read EVERY original1892 caption and its source-event context, or bibliographic metadata, and review the Russian draft for complete fidelity and natural concise Russian. Correct all errors, including omitted subjects, metaphors and speaker perspective. The source captions are authentic original quotation displays; preserve their full wording and quotation role. Literal image alt text is contextual evidence, not replacement caption wording. Do not invent image details. For metadata preserve approved title Приключения Шерлока Холмса, author Артур Конан Дойл, genre Сборник рассказов. Return JSON only with every row in order in rows(source_id,target) and review(source_id,verdict PASS or CORRECTED,reason).'
 if phase:task+=' Separately compare EVERY CURRENT final_rows target against original source and every prior correction. If already faithful, retain exact current bytes and verdict PASS. CORRECTED means you actually changed current bytes.'
 payload={'task':task,'phase':'INDEPENDENT_SOURCE_COMPARISON' if phase else 'COMPLETE_SOURCE_ALIGNED_CAPTION_AND_METADATA_REVIEW','source_rows':sources,'final_rows':current,'prior_corrections':[c for t in turns for c in t['corrections']]};result,meta=api.checked_call(api.SYSTEM,payload,O/f'phase{phase:02}',sources,True);changes=[{'source_id':a['source_id'],'before':a['target'],'after':b['target']} for a,b in zip(current,result['rows']) if a['target']!=b['target']];turns.append({'phase':phase,'api':meta,'review':result['review'],'corrections':changes});current=result['rows'];api.save(O/'pending.json',{'rows':current,'turns':turns});print('CAPTION_PHASE',phase,'CORRECTIONS',len(changes),flush=True)
 if phase>=1 and not changes and all(r['verdict']=='PASS' for r in result['review']):break
else:raise RuntimeError('CAPTION_SOURCE_COMPARISON_NOT_STABLE')
