subprocess.run(['git','add','results/ru45-captions'],cwd=R,check=True);subprocess.run(['git','commit','-m','Preserve actual19-row caption and metadata review with independent comparison'],cwd=R,check=True);subprocess.run(['git','push','origin','HEAD'],cwd=R,check=True);print('ALL19_SOURCE_COMPARED',flush=True)
